package ru.kyro.hud;

import java.lang.reflect.*;
import java.util.*;
import com.google.gson.*;

/** Reflection is resolved once per class/member, never by guessing numeric field order. */
final class GameAccess {
    static final JsonObject MAP=BadgeHooks.MAPPINGS;
    static final Map<String,String> REVERSE=new HashMap<>();
    static final Map<String,Optional<Field>> FIELDS=new java.util.concurrent.ConcurrentHashMap<>();
    static final Map<String,java.util.List<Method>> METHODS=new java.util.concurrent.ConcurrentHashMap<>();
    static final Map<Class<?>,String> CANONICAL=new java.util.concurrent.ConcurrentHashMap<>();
    static final Map<String,String> RUNTIME_METHODS=new java.util.concurrent.ConcurrentHashMap<>();
    static final Map<String,Method> RESOLVER_METHODS=new HashMap<>();
    static Object resolver;static Class<?> resolverApi;static long resolverRetry;
    static synchronized Object resolve(String method,String...args){try{
        if(resolver==null){if(System.nanoTime()<resolverRetry)return null;resolverRetry=System.nanoTime()+100_000_000L;ClassLoader loader=Thread.currentThread().getContextClassLoader();Class<?> api=Class.forName("net.fabricmc.loader.api.FabricLoader",false,loader);Object instance=api.getMethod("getInstance").invoke(null);resolver=api.getMethod("getMappingResolver").invoke(instance);resolverApi=Class.forName("net.fabricmc.loader.api.MappingResolver",false,loader);Object namespaces=resolverApi.getMethod("getNamespaces").invoke(resolver);if(!(namespaces instanceof Collection)||!((Collection<?>)namespaces).contains("official")){resolver=null;return null;}}
        Method target=RESOLVER_METHODS.get(method);if(target==null){Class<?>[] types=new Class<?>[args.length];Arrays.fill(types,String.class);target=resolverApi.getMethod(method,types);RESOLVER_METHODS.put(method,target);}return target.invoke(resolver,(Object[])args);
    }catch(Throwable ignored){return null;}}
    static {if(MAP.has("moduleClasses"))for(Map.Entry<String,JsonElement> e:MAP.getAsJsonObject("moduleClasses").entrySet())REVERSE.put(e.getValue().getAsString(),e.getKey());}
    static String canonical(Class<?> type){String cached=CANONICAL.get(type);if(cached!=null)return cached;String name=type.getName(),value=name;if(type.isArray())value=canonical(type.getComponentType())+"[]";else if(REVERSE.containsKey(name))value=REVERSE.get(name);else if(name.startsWith("net.minecraft.")){Object official=resolve("unmapClassName","official",name);if(official instanceof String&&REVERSE.containsKey(official))value=REVERSE.get(official);}if(!name.startsWith("net.minecraft.class_")||!value.equals(name))CANONICAL.put(type,value);return value;}
    static String officialClass(String name){return MAP.has("moduleClasses")&&MAP.getAsJsonObject("moduleClasses").has(name)?MAP.getAsJsonObject("moduleClasses").get(name).getAsString():name;}
    static String className(String name){String official=officialClass(name);if(official.equals(name)&&!name.startsWith("net.minecraft."))return name;Object runtime=resolve("mapClassName","official",official);return runtime instanceof String?(String)runtime:official;}
    static java.util.List<Class<?>> hierarchy(Class<?> type){LinkedHashSet<Class<?>> result=new LinkedHashSet<>();parents(type,result);return new ArrayList<>(result);}
    static void parents(Class<?> type,Set<Class<?>> result){if(type==null||!result.add(type))return;for(Class<?> i:type.getInterfaces())parents(i,result);parents(type.getSuperclass(),result);}
    static java.util.List<String> names(Class<?> type,String member){LinkedHashSet<String> names=new LinkedHashSet<>();names.add(member);for(Class<?> c:hierarchy(type))addNames(names,canonical(c),member);return new ArrayList<>(names);}
    static String descriptor(String type,boolean runtime){if(type.endsWith("[]"))return "["+descriptor(type.substring(0,type.length()-2),runtime);String[] all="void:boolean:byte:char:short:int:long:float:double".split(":");String codes="VZBCSIJFD";for(int i=0;i<all.length;i++)if(type.equals(all[i]))return ""+codes.charAt(i);return "L"+(runtime?className(type):officialClass(type)).replace('.','/')+";";}
    static String descriptor(JsonObject spec,boolean runtime){StringBuilder desc=new StringBuilder("(");for(JsonElement arg:spec.getAsJsonArray("args"))desc.append(descriptor(arg.getAsString(),runtime));return desc.append(')').append(descriptor(spec.get("returns").getAsString(),runtime)).toString();}
    static String methodName(String owner,JsonObject spec){String original=spec.get("name").getAsString(),desc=descriptor(spec,false),key=owner+"#"+original+desc;String cached=RUNTIME_METHODS.get(key);if(cached!=null)return cached;Object mapped=resolve("mapMethodName","official",officialClass(owner),original,desc);if(mapped instanceof String){RUNTIME_METHODS.put(key,(String)mapped);return (String)mapped;}return original;}

    static JsonArray signatures(String owner,String member){if(!MAP.has("moduleSignatures"))return null;JsonElement value=MAP.getAsJsonObject("moduleSignatures").get(owner+"#"+member);return value==null?null:value.getAsJsonArray();}
    static Set<String> methodNames(Class<?> type,String owner,JsonObject spec){Set<String> names=new LinkedHashSet<>();names.add(methodName(owner,spec));String original=spec.get("name").getAsString(),desc=descriptor(spec,false);for(Class<?> parent:hierarchy(type)){if(!parent.isInterface())continue;String key=canonical(parent)+"#"+original+desc;String name=RUNTIME_METHODS.get(key);if(name==null){Object mapped=resolve("mapMethodName","official",officialClass(canonical(parent)),original,desc);if(mapped instanceof String){name=(String)mapped;RUNTIME_METHODS.put(key,name);}}if(name!=null)names.add(name);}return names;}
    static boolean matches(String owner,String actual,String member,String desc){JsonArray list=signatures(owner,member);if(list==null)return actual.equals(member);for(JsonElement e:list){JsonObject s=e.getAsJsonObject();if(methodName(owner,s).equals(actual)&&descriptor(s,true).equals(desc))return true;}return false;}
    static boolean signature(Class<?> type,Method method,String member){boolean mapped=false;for(Class<?> owner:hierarchy(type)){JsonArray list=signatures(canonical(owner),member);if(list==null)continue;mapped=true;for(JsonElement entry:list){JsonObject spec=entry.getAsJsonObject();if(!(method.getName().equals(member)||methodNames(type,canonical(owner),spec).contains(method.getName()))||!canonical(method.getReturnType()).equals(spec.get("returns").getAsString()))continue;JsonArray params=spec.getAsJsonArray("args");Class<?>[] actual=method.getParameterTypes();if(params.size()!=actual.length)continue;boolean same=true;for(int i=0;i<actual.length;i++)if(!canonical(actual[i]).equals(params.get(i).getAsString()))same=false;if(same)return true;}}return !mapped&&method.getName().equals(member);}
    static void addNames(Set<String> names,String owner,String member){if(MAP.has("moduleMembers")){JsonElement v=MAP.getAsJsonObject("moduleMembers").get(owner+"#"+member);if(v!=null)for(JsonElement e:v.getAsJsonArray())names.add(e.getAsString());}if(MAP.has("moduleFields")){JsonElement v=MAP.getAsJsonObject("moduleFields").get(owner+"#"+member);if(v!=null){JsonObject f=v.getAsJsonObject();Object mapped=resolve("mapFieldName","official",officialClass(owner),f.get("name").getAsString(),descriptor(f.get("type").getAsString(),false));if(mapped instanceof String)names.add((String)mapped);}}}
    static boolean matches(String owner,String actual,String member){if(actual.equals(member))return true;if(!MAP.has("moduleMembers"))return false;JsonElement list=MAP.getAsJsonObject("moduleMembers").get(owner+"#"+member);if(list!=null)for(JsonElement e:list.getAsJsonArray())if(e.getAsString().equals(actual))return true;return false;}
    static Field reflectedField(Class<?> type,String member){
        for(Class<?> owner:hierarchy(type)){
            JsonElement value=MAP.has("moduleFields")?MAP.getAsJsonObject("moduleFields").get(canonical(owner)+"#"+member):null;
            if(value==null)continue;JsonObject spec=value.getAsJsonObject();String original=spec.get("name").getAsString();Object mapped=resolve("mapFieldName","official",officialClass(canonical(owner)),original,descriptor(spec.get("type").getAsString(),false));
            for(String name:new String[]{member,mapped instanceof String?(String)mapped:original,original})try{Field field=owner.getDeclaredField(name);if(!canonical(field.getType()).equals(spec.get("type").getAsString()))continue;field.setAccessible(true);return field;}catch(Exception ignored){}
        }
        for(Class<?> owner:hierarchy(type))try{Field field=owner.getDeclaredField(member);field.setAccessible(true);return field;}catch(Exception ignored){}
        return null;
    }
    static Object field(Object target,String member){if(target==null)return null;Class<?> type=target instanceof Class?(Class<?>)target:target.getClass();String key=type.getName()+"#"+member;Optional<Field> cached=FIELDS.get(key);if(cached==null){Field found=reflectedField(type,member);cached=Optional.ofNullable(found);FIELDS.put(key,cached);}try{return cached.isPresent()?cached.get().get(target instanceof Class?null:target):null;}catch(Exception ignored){return null;}}
    static Object callExact(Object target,String member,Object...args){if(target==null)return null;Class<?> type=target instanceof Class?(Class<?>)target:target.getClass();String key=type.getName()+"#"+member+"/"+args.length;java.util.List<Method> list=METHODS.get(key);if(list==null){list=new ArrayList<>();Set<String> accepted=new HashSet<>(names(type,member));for(Class<?> owner:hierarchy(type)){JsonArray specs=signatures(canonical(owner),member);if(specs!=null)for(JsonElement spec:specs)accepted.addAll(methodNames(type,canonical(owner),spec.getAsJsonObject()));}LinkedHashSet<Method> candidates=new LinkedHashSet<>(Arrays.asList(type.getMethods()));for(Class<?> c=type;c!=null;c=c.getSuperclass())candidates.addAll(Arrays.asList(c.getDeclaredMethods()));for(Method m:candidates)if(accepted.contains(m.getName())&&m.getParameterTypes().length==args.length&&signature(type,m,member))try{m.setAccessible(true);list.add(m);}catch(Exception ignored){}METHODS.put(key,list);}for(Method m:list)try{return m.invoke(target instanceof Class?null:target,args);}catch(IllegalArgumentException ignored){}catch(Exception ignored){return null;}return null;}
    static Object call(Object target,String member,Object...args){Object value=callExact(target,member,args);if(value!=null||target==null)return value;String alias=null;switch(member){case "getMainCamera":alias="mainCamera";break;case "position":alias="getPosition";break;case "xRot":alias="getXRot";break;case "yRot":alias="getYRot";break;case "refreshTrimmedMessages":alias="rescaleChat";break;}if(alias!=null)value=callExact(target,alias,args);if(value==null&&args.length==0){String fieldName=member.equals("getInventory")?"inventory":member.equals("onGround")?"onGround":member.equals("getX")?"x":member.equals("getY")?"y":member.equals("getZ")?"z":null;if(fieldName!=null)value=field(target,fieldName);}return value;}
    static Class<?> type(String name,ClassLoader loader){try{return Class.forName(className(name),false,loader);}catch(Throwable ignored){try{return Class.forName(name,false,loader);}catch(Throwable missing){return null;}}}
    static double number(Object v,double fallback){return v instanceof Number?((Number)v).doubleValue():fallback;}
    static String text(Object value){if(value==null)return "";if(value instanceof String)return (String)value;Object text=call(value,"getString");return text instanceof String?(String)text:"";}
    static Object literal(ClassLoader loader,String text){Object component=call(type("net.minecraft.network.chat.Component",loader),"literal",text);if(component!=null)return component;try{Class<?> legacy=type("net.minecraft.network.chat.TextComponent",loader);return legacy==null?null:legacy.getConstructor(String.class).newInstance(text);}catch(Exception ignored){return null;}}
    static Object position(Object entity){Object value=call(entity,"position");return value!=null?value:call(entity,"getPosition");}
    static double axis(Object vector,String axis){Object v=call(vector,axis);if(!(v instanceof Number))v=field(vector,axis);return number(v,0);}
}
